// Block (composition) — a full-width page heading with optional context and actions.
// Contract: docs/rules/block-contract.md. Arranges only (Stack for layout);
// breadcrumb content is supplied by the consumer. Owns no Component look; mints no tokens.
import type { ReactNode, Ref } from "react";
import { Stack } from "../layouts/Stack";
import "./PageHeader.css";

export interface PageHeaderProps {
  /** Page title. */
  title: string;
  /** Supporting context shown below the title. */
  description?: string;
  /** Breadcrumbs row supplied by the consumer. */
  breadcrumbs?: ReactNode;
  /** Page-level actions aligned opposite the title on desktop. */
  actions?: ReactNode;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function PageHeader({
  title,
  description,
  breadcrumbs,
  actions,
  className,
  ref,
}: PageHeaderProps) {
  return (
    // A div, not a <header>: placed at page level a <header> is an implicit `banner` landmark, and
    // the page's banner belongs to the shell whose header slot this sits in (AppShell renders one).
    // A second banner inside it is an axe violation on every Screen; Calendar made the same call.
    <Stack
      ref={ref}
      gap="small"
      className={className ? `sd-pageheader ${className}` : "sd-pageheader"}
    >
      {/* Below medium the actions stack under the title, so the title and the breadcrumbs above it
          take the inset (rule 8). */}
      {breadcrumbs && (
        <>
          <div className="sd-pageheader__breadcrumbs">{breadcrumbs}</div>
        </>
      )}
      {/* spacing: attachment — the breadcrumbs name where the title sits */}
      <Stack
        direction={{ small: "column", medium: "row" }}
        justify="between"
        align={{ small: "stretch", medium: "center" }}
        gap="small"
        className="sd-pageheader__content"
      >
        <>
          <Stack gap="x-small" className="sd-pageheader__heading">
            <h1 className="sd-pageheader__title sd-type-headline-medium">{title}</h1>
            {description && (
              <p className="sd-pageheader__description sd-type-body-medium">{description}</p>
            )}
          </Stack>
        </>
        {actions}
      </Stack>
    </Stack>
  );
}

/* PageHeader.css — .sd-pageheader (Block)
   Arrangement only: fills its available width and removes native text margins.
   Grouping and responsive alignment are owned by Stack. No width cap or new tokens. */
.sd-pageheader {
  width: 100%;
}

.sd-pageheader__title,
.sd-pageheader__description {
  margin: 0;
}

.sd-pageheader__description {
  color: var(--sd-color-text-muted);
}
